# Model lift capacity at every lifting-chart cell from hma.machine.statics.lift, ~1.7 s a cell.
# `python -m hma.task.capacity` rewrites hma/task/capacity_table.py after any machine change.
from __future__ import annotations

import argparse
from pathlib import Path

from hma.machine import statics
from hma.task.body import SIDE_ROWS

TABLE_PATH = Path(__file__).with_name("capacity_table.py")
HEADER = (
    "# Generated by `python -m hma.task.capacity` from hma.machine.statics.lift; do not edit.\n"
    "# (height m, radius m): (over-side tipping load kg, hydraulic capacity kg at main relief).\n"
)


def cells() -> list[tuple[float, float]]:
    return sorted((c.height_m, c.radius_m) for row in SIDE_ROWS.values() for c in row)


def compute() -> dict[tuple[float, float], tuple[float, float] | None]:
    machine = statics.Machine()
    table = {}
    try:
        for height, radius in cells():
            found = statics.lift(machine, height, radius, statics.MAIN_RELIEF)
            table[(height, radius)] = (
                None if found is None
                else (round(float(found["side_tip"]), 1), round(float(found["hydraulic"]), 1))
            )
    finally:
        machine.done()
    return table


def render(table: dict[tuple[float, float], tuple[float, float] | None]) -> str:
    rows = "".join(f"    {key!r}: {value!r},\n" for key, value in table.items())
    return f"{HEADER}TABLE = {{\n{rows}}}\n"


def main() -> None:
    argparse.ArgumentParser(description="Rewrite the model lift capacity table.").parse_args()
    TABLE_PATH.write_text(render(compute()), encoding="utf-8", newline="\n")
    print(f"wrote {len(cells())} cells to {TABLE_PATH.name}")


if __name__ == "__main__":
    main()
